#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

bool flag[2] = {false, false};
int turn;
int balance = 10000;

void *thread0(void *arg) {
    flag[0] = true;
    turn = 1;
    while (flag[1] && turn == 1) {}
    balance += 500;
    flag[0] = false;
    return NULL;
}

void *thread1(void *arg) {
    flag[1] = true;
    turn = 0;
    while (flag[0] && turn == 0) {}
    balance += 500;
    flag[1] = false;
    return NULL;
}

int main(void) {
    pthread_t t0, t1;
    pthread_create(&t0, NULL, thread0, NULL);
    pthread_create(&t1, NULL, thread1, NULL);
    pthread_join(t0, NULL);
    pthread_join(t1, NULL);
    printf("Final balance = %d\n", balance);
    return 0;
}

